<?php
use Illuminate\Support\Facades\Route; use App\Http\Controllers\{VaultController,ProjectController,CredentialController,ResourceUrlController,PlanController,SecurityController,BackupController,SearchController};
Route::get('/',fn()=>session()->has('vault_key')?redirect()->route('dashboard'):redirect()->route('vault.login'));
Route::get('/vault',[VaultController::class,'login'])->name('vault.login'); Route::post('/vault/unlock',[VaultController::class,'unlock'])->name('vault.unlock')->middleware('throttle:5,1'); Route::post('/vault/setup',[VaultController::class,'setup'])->name('vault.setup')->middleware('throttle:3,1'); Route::get('/vault/mfa',[VaultController::class,'mfa'])->name('vault.mfa'); Route::post('/vault/mfa',[VaultController::class,'verifyMfa'])->name('vault.mfa.verify')->middleware('throttle:5,1'); Route::post('/vault/lock',[VaultController::class,'lock'])->name('vault.lock');
Route::middleware('vault.unlocked')->group(function(){Route::get('/dashboard',[VaultController::class,'dashboard'])->name('dashboard');Route::get('/search',SearchController::class)->name('search');Route::resource('projects',ProjectController::class)->except(['destroy']);Route::post('/projects/{project}/archive',[ProjectController::class,'archive'])->name('projects.archive');Route::resource('credentials',CredentialController::class)->except(['show']);Route::post('/credentials/{credential}/favorite',[CredentialController::class,'toggleFavorite'])->name('credentials.favorite');Route::post('/credentials/{credential}/reveal',[CredentialController::class,'reveal'])->name('credentials.reveal')->middleware('throttle:30,1');Route::resource('urls',ResourceUrlController::class)->except(['show']);Route::resource('plans',PlanController::class)->except(['show']);Route::get('/security',[SecurityController::class,'index'])->name('security.index');Route::post('/security/mfa/begin',[SecurityController::class,'beginMfa'])->name('security.mfa.begin');Route::post('/security/mfa/confirm',[SecurityController::class,'confirmMfa'])->name('security.mfa.confirm')->middleware('throttle:5,1');Route::post('/security/mfa/cancel',[SecurityController::class,'cancelMfaSetup'])->name('security.mfa.cancel');Route::post('/security/mfa/disable',[SecurityController::class,'disableMfa'])->name('security.mfa.disable')->middleware('throttle:3,1');Route::post('/security/mfa/recovery/regenerate',[SecurityController::class,'regenerateRecovery'])->name('security.mfa.recovery.regenerate')->middleware('throttle:3,1');Route::post('/security/master-password',[SecurityController::class,'changeMaster'])->name('security.master.change')->middleware('throttle:3,1');Route::get('/backup',[BackupController::class,'index'])->name('backup.index');Route::get('/backup/export',[BackupController::class,'export'])->name('backup.export');Route::post('/backup/restore',[BackupController::class,'restore'])->name('backup.restore')->middleware('throttle:3,1');});
